 function diaryList(){return <UI.div className="diary-list">{['Breakfast','Lunch','Dinner','Snack'].map((m,i)=><UI.div className="meal-section" key={m}><UI.div className="section-title"><UI.span className="meal-icon">{['☀','◒','☾','◈'][i]}</UI.span><UI.h3>{m}</UI.h3><UI.span className="muted">{Math.round(meals.filter(r=>r.payload.meal===m).reduce((a,r)=>a+r.payload.calories,0))} kcal</UI.span><UI.button className="icon" aria-label={`Add ${m}`} onClick={()=>{openMeal();setMeal({...emptyMeal,meal:m});}}><Plus size={18}/></UI.button></UI.div>{meals.filter(r=>r.payload.meal===m).map(r=><UI.div className="entry" key={r.id}><UI.div><UI.strong>{r.payload.name}</UI.strong>{r.payload.photoId&&<UI.img className="meal-thumbnail" src={'/api/meal-photo?id='+encodeURIComponent(r.payload.photoId)} alt="Logged meal photo"/>}<UI.small>P {r.payload.protein}g · C {r.payload.carbs}g · Fiber {r.payload.fiber}g</UI.small></UI.div><UI.b>{r.payload.calories} <UI.small>kcal</UI.small></UI.b><UI.button className="icon" aria-label={`Edit ${r.payload.name}`} onClick={()=>editEntry(r)}><Pencil size={15}/></UI.button><UI.button className="icon danger" aria-label={`Delete ${r.payload.name}`} onClick={()=>remove(r.id)}><Trash2 size={15}/></UI.button></UI.div>)}{!meals.some(r=>r.payload.meal===m)&&<UI.p className="emptyline">No meal logged yet. <UI.button className="text-link" onClick={()=>{openMeal();setMeal({...emptyMeal,meal:m});}}>Add food</UI.button></UI.p>}</UI.div>)}</UI.div>}
